(* [comment removed for export] *)
Lemma arr255_cell : forall M p n i, arr255 M p n -> 0 <= i < n ->
  exists v, 0 <= v <= 255 /\ rdn segs M (Z_to_bv 64 (p + 4 * i)) 4 = Some (Z_to_le_bytes 4 v).
Proof.
